import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;
  const root = new Group();

  // Prepare cleanup containers
  root.userData.handlers = {};
  root.userData._primitives = [];

  // Load GLB mesh
  if (config?.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      root.add(gltf.scene);
    });
  }

  // Apply cinematic primitives if any
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((p) => {
      const primFn = ctx.primitives[p.name];
      if (typeof primFn === 'function') {
        const instance = primFn(root, p.params);
        if (instance) root.userData._primitives.push(instance);
      }
    });
  }

  // Hover lift (rise‑in) effect
  const hoverIn = gsap.timeline({ paused: true });
  hoverIn.to(root.position, { y: '+=0.15', duration: 0.7, ease: 'power3.out' });
  const hoverOut = gsap.timeline({ paused: true });
  hoverOut.to(root.position, { y: '-=0.15', duration: 0.7, ease: 'power3.out' });

  // Click press‑down effect
  const clickAnim = gsap.timeline({ paused: true });
  clickAnim
    .to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' })
    .to(root.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'power4.out' });

  // Event handlers
  root.userData.handlers.hover = (isHover) => {
    if (isHover) {
      hoverOut.pause();
      hoverIn.restart();
    } else {
      hoverIn.pause();
      hoverOut.restart();
    }
  };
  root.userData.handlers.click = () => {
    clickAnim.restart();
    ctx.emit('hub-home.select');
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    hoverIn.kill();
    hoverOut.kill();
    clickAnim.kill();
    root.userData._primitives.forEach((inst) => {
      if (inst && typeof inst.cleanup === 'function') inst.cleanup();
    });
    // Dispose GLB resources if they exist
    root.traverse((obj) => {
      if (obj.isMesh && obj.geometry) obj.geometry.dispose();
      if (obj.isMesh && obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m && m.dispose && m.dispose());
        } else {
          obj.material.dispose && obj.material.dispose();
        }
      }
    });
  };

  return root;
}
